NORDIC_INCL = ('all transfers and rail or ferry journeys as listed; sightseeing and cruises as listed with tickets where stated; daily breakfast')
NORDIC_NOT = ('Not included: international flights; Schengen visa fees; lunches and dinners unless stated; travel insurance; '
              'optional excursions; personal expenses. Hotels are quoted as a class and named on confirmation.')
UK_NOT = NORDIC_NOT.replace('Schengen visa fees', 'Irish visa fees')


def stop(city, days, nights, hotel, blurb, program, acts=(), name=None, stars=3, meal='Breakfast'):
    s = {'city': city, 'name': name or city, 'days': days, 'nights': nights, 'hotel': hotel, 'blurb': blurb,
         'program': program, 'acts': list(acts), 'stars': stars, 'meal': meal}
    return s


def trip(key, **kw):
    kw.setdefault('included', 'Included: ' + NORDIC_INCL + '.')
    kw.setdefault('not_included', NORDIC_NOT)
    kw.setdefault('tags', [kw['tag'], 'Multi-country' if kw.get('multi') else 'Nature'])
    kw.pop('multi', None)
    TRIPS[key] = kw


ARR = ['Arrival at the airport and private transfer to your hotel', 'Check in and the rest of the day at leisure']
DEP = lambda city: ('Departure from %s' % city, ['Breakfast at the hotel and check out', 'Transfer to the airport for your flight home'], 'B')

